    "ce": "# An arrow that changes its ends — exported by Manim Formula Editor for ManimCE 0.22.\n# Render at 1920×1080, 60 fps:\n#     manim -r 1920,1080 --fps 60 AnArrowThatChangesItsEnds.py AnArrowThatChangesItsEnds\n# Every play and wait lasts a whole number of frames at 60 fps, so the video has\n# exactly 720 frames, like the editor's video export.\nfrom manim import *\n\n\ndef _glyphs(tex, layout):\n    \"\"\"The glyphs of `tex` in the editor's order. That order (MathJax's, or another\n    template's) can differ from Manim's, so the glyphs are matched by position: `layout`\n    holds each glyph's (x, y, width, height) relative to the formula centre, divided by the\n    formula height, and every real glyph is assigned to one entry with the least total\n    distance. Entries without a counterpart get an empty VMobject.\"\"\"\n    from scipy.optimize import linear_sum_assignment\n\n    real = tex.family_members_with_points()\n    glyphs = [VMobject() for _ in layout]\n    if len(real) != len(layout):\n        print(f\"Warning: Manim made {len(real)} glyphs of a formula the editor split into \"\n              f\"{len(layout)}; unmatched glyphs are not animated.\")\n    if not real or not layout:\n        return glyphs  # nothing to match (a formula without ink, such as \\quad)\n    centre, height = tex.get_center(), tex.get_height()\n    if height < 1e-6:\n        height = 1.0  # a flat mobject (a rule): the editor's layout is divided by 1 then too\n    have = np.array([\n        [*((g.get_center() - centre)[:2] / height), g.get_width() / height, g.get_height() / height]\n        for g in real\n    ])\n    want = np.array(layout, dtype=float)\n    cost = np.linalg.norm(want[:, None, :] - have[None, :, :], axis=2)\n    for i, j in zip(*linear_sum_assignment(cost)):\n        glyphs[i] = real[j]\n    return glyphs\n\n\nclass AnArrowThatChangesItsEnds(Scene):\n    def construct(self):\n        self.camera.background_color = \"#000000\"\n\n        # a: A\n        a = MathTex(r\"A\", font_size=144)\n        a_g = _glyphs(a, [\n            (0, 0, 0.9651, 1),\n        ])\n        a.move_to([-5, -1.8, 0])\n\n        # b: B\n        b = MathTex(r\"B\", font_size=144)\n        b_g = _glyphs(b, [\n            (0, 0, 1.0556, 1),\n        ])\n        b.move_to([5, -1.8, 0])\n        b.set_z_index(1)\n\n        # c: C\n        c = MathTex(r\"C\", font_size=144)\n        c_g = _glyphs(c, [\n            (0, 0, 0.9766, 1),\n        ])\n        c.move_to([0, 2.2, 0])\n        c.set_z_index(2)\n\n        # l1: arrow, built on a and b where its clip starts\n\n        # 0 s – 0.5 s: a fade_in, b fade_in, c fade_in\n        self.play(FadeIn(a), FadeIn(b), FadeIn(c), run_time=0.5)\n        # 0.5 s – 0.8 s\n        self.wait(0.3)\n        l1 = Arrow(a.get_right(), b.get_left(), color=\"#FFFF00\")\n        l1.set_z_index(3)\n        self.add(l1)\n        # 0.8 s – 4 s\n        self.wait(3.2)\n        l1_to = Arrow(a.get_right(), c.get_corner(DL), color=\"#FFFF00\")\n        # 4 s – 5 s: l1 tween\n        self.play(Transform(l1, l1_to), run_time=1)\n        # 5 s – 7 s\n        self.wait(2)\n        l1_to_2 = Arrow(b.get_left(), c.get_corner(DL), color=\"#FFFF00\")\n        # 7 s – 8 s: l1 tween\n        self.play(Transform(l1, l1_to_2), run_time=1)\n        # 8 s – 11.4 s\n        self.wait(3.4)\n        # 11.4 s – 12 s: a fade_out, b fade_out, c fade_out\n        self.play(FadeOut(a), FadeOut(b), FadeOut(c), run_time=0.6)\n",
